import ResumeUpload from "../components/ResumeUpload";
import { useSearchParams } from "react-router-dom";

function UploadPage() {
  const [searchParams] = useSearchParams();
  const jobId = searchParams.get('jobId');

  return (
    <div className="page container">
      <div className="upload-grid">
        <div>
          <h2>Upload Resume</h2>
          {jobId && <p className="badge bg-info">Applying to Job ID: {jobId}</p>}
          <p className="muted">Drop your resume here and we'll analyze skills, score, and recommend interview eligibility.</p>
          <ul>
            <li>Accepts .pdf, .doc, .docx</li>
            <li>Quick results and clear match score</li>
            <li>Saved to your dashboard</li>
          </ul>
        </div>
        <div>
          <ResumeUpload jobId={jobId} />
        </div>
      </div>
    </div>
  );
}

export default UploadPage;
